for path, text in NOTES.items():
    with io.open(path, "r", encoding="utf-8", newline="") as handle:
        content = handle.read()
    newline = "\r\n" if "\r\n" in content else "\n"
    if H in content:
        continue
    if not content.endswith(newline):
        content += newline
    block = newline.join(["", H, "", text, ""]).replace("\n", newline) if newline == "\n" else newline.join(["", H, "", text.replace("\n", newline), ""])
    with io.open(path, "w", encoding="utf-8", newline="") as handle:
        handle.write(content + block)
print(len(NOTES), "files")
